<script setup>
import AdminNavigation from '@/Components/Admin/AdminNavigation.vue'; import PortalLayout from '@/Layouts/PortalLayout.vue'; import { Head,Link,router } from '@inertiajs/vue3'; import { reactive } from 'vue'; const props=defineProps({customers:{type:Object,required:true},filters:{type:Object,required:true},assignees:{type:Array,required:true},sources:{type:Array,required:true}}); const filters=reactive({search:props.filters.search||'',status:props.filters.status||'',type:props.filters.type||'',source:props.filters.source||'',assigned_to:props.filters.assigned_to||''}); const apply=()=>router.get(route('admin.customers.index'),filters,{preserveState:true,replace:true}); const reset=()=>router.get(route('admin.customers.index'));
</script>
<template><Head title="Customers"/><PortalLayout area="Administration"><template #navigation><AdminNavigation active="customers"/></template><div class="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><h1 class="text-3xl font-bold">Customers</h1><p class="mt-2 text-slate-600">Manage leads, organisations, contacts, and product relationships.</p></div><Link :href="route('admin.customers.create')" class="form-button text-center">Create customer</Link></div><div v-if="$page.props.flash.success" class="success-message mb-5">{{ $page.props.flash.success }}</div><form class="mb-6 grid gap-3 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm md:grid-cols-3 xl:grid-cols-6" @submit.prevent="apply"><label class="xl:col-span-2"><span class="sr-only">Search customers</span><input v-model="filters.search" placeholder="Name, number, email or phone" class="w-full"/></label><label><span class="sr-only">Status</span><select v-model="filters.status" class="w-full"><option value="">All statuses</option><option v-for="status in ['lead','prospect','active','suspended','inactive']" :key="status" :value="status">{{ status }}</option></select></label><label><span class="sr-only">Type</span><select v-model="filters.type" class="w-full"><option value="">All types</option><option value="organization">Organization</option><option value="individual">Individual</option></select></label><label><span class="sr-only">Assigned to</span><select v-model="filters.assigned_to" class="w-full"><option value="">All owners</option><option v-for="user in assignees" :key="user.id" :value="user.id">{{ user.name }}</option></select></label><div class="flex gap-2"><button class="form-button !px-4 !py-2">Filter</button><button type="button" class="rounded-xl border border-slate-300 px-3 font-bold" @click="reset">Clear</button></div></form><div class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="hidden grid-cols-[1.4fr_.8fr_.7fr_.8fr_auto] gap-4 border-b bg-slate-50 px-5 py-3 text-xs font-bold uppercase text-slate-500 md:grid"><span>Customer</span><span>Status</span><span>Type</span><span>Owner</span><span></span></div><div v-for="customer in customers.data" :key="customer.id" class="grid gap-3 border-b border-slate-100 p-5 last:border-0 md:grid-cols-[1.4fr_.8fr_.7fr_.8fr_auto] md:items-center"><div><Link :href="route('admin.customers.show',customer.id)" class="font-bold text-[#0B3D6E] hover:text-[#0797A5]">{{ customer.name }}</Link><p class="text-sm text-slate-500">{{ customer.customer_number }}<span v-if="customer.email"> · {{ customer.email }}</span></p></div><span class="w-fit rounded-full bg-slate-100 px-2.5 py-1 text-xs font-bold uppercase">{{ customer.status }}</span><span class="text-sm capitalize text-slate-600">{{ customer.type }}</span><span class="text-sm text-slate-600">{{ customer.assigned_user?.name||'Unassigned' }}</span><Link :href="route('admin.customers.edit',customer.id)" class="rounded-lg border border-slate-300 px-4 py-2 text-center text-sm font-bold">Edit</Link></div><div v-if="!customers.data.length" class="p-10 text-center text-slate-500">No customers match these filters.</div></div><nav v-if="customers.meta.last_page>1" class="mt-5 flex flex-wrap gap-2" aria-label="Pagination"><Link v-for="link in customers.meta.links" :key="link.label" :href="link.url||'#'" preserve-scroll class="rounded-lg border px-3 py-2 text-sm" :class="[link.active?'border-cyan-600 bg-cyan-50 text-cyan-800':'border-slate-300',!link.url?'pointer-events-none opacity-40':'']" v-html="link.label"/></nav></PortalLayout></template>
